SOURCE_CLAIM_JSON: {"title":"Gobernar no debe ser hegemonía, sino búsqueda de bienestar para los pueblos: presidente","publisher":"Presidencia de México","publication_date":"2022-09-16","url":"https://www.gob.mx/amlo/prensa/gobernar-no-debe-ser-hegemonia-sino-busqueda-de-bienestar-para-los-pueblos-presidente","claim":"AMLO proposed a UN-backed dialogue committee and a five-year truce for the Russia-Ukraine war, including suspension of military provocations and missile or nuclear tests.","locator":"Lines 62-71","provisional_id":"E-AMLO22-2B-01","canonical_fact_key":"https://www.gob.mx/amlo/prensa/gobernar-no-debe-ser-hegemonia-sino-busqueda-de-bienestar-para-los-pueblos-presidente|62-71|AMLO Ukraine dialogue and five-year truce proposal","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.1","2B.3","2B.7","2B.8","2B.10"],"source_type":"presidential statement","source_confidence":"high","source_confidence_reason":"Contemporaneous official presidential record with direct quoted remarks and proposal details.","final_evidence_use":"final_evidence","period_fit":"Directly dated 16 September 2022.","ruler_attribution":"Direct personal attribution to AMLO's public diplomacy and stated crisis approach; proposal was to be advanced through the Foreign Ministry.","contrary_evidence":["The proposal's feasibility and reception are not established here; its criticism of NATO, sanctions, and arms support may be viewed as politically one-sided."],"lenses":["2B.1","2B.3","2B.7","2B.8","2B.10"]}

SOURCE_CLAIM_JSON: {"title":"UN Secretary-General's remarks to Security Council meeting on Ukraine","publisher":"United Nations","publication_date":"2022-09-22","url":"https://ukraine.un.org/en/200613-un-secretary-generals-remarks-security-council-meeting-ukraine","claim":"The UN Secretary-General described Russia's war as ongoing, warned that annexation through force violated the UN Charter, and called for ending the war and preventing escalation.","locator":"Lines 59-83 and 150-156","provisional_id":"E-AMLO22-2B-02","canonical_fact_key":"https://ukraine.un.org/en/200613-un-secretary-generals-remarks-security-council-meeting-ukraine|59-83,150-156|UN escalation and annexation context","disposition":"context","chapter_ids":["2B"],"methodology_ids":["2B.1","2B.2","2B.4","2B.7","2B.10"],"source_type":"UN Security Council remarks","source_confidence":"high","source_confidence_reason":"Primary UN contemporaneous record.","final_evidence_use":"context","period_fit":"Directly dated 22 September 2022.","ruler_attribution":"No direct attribution to AMLO; provides the international crisis context in which Mexico's proposal was made.","contrary_evidence":["The statement does not evaluate Mexico's neutrality, proposal, or voting behavior."],"lenses":["2B.1","2B.2","2B.4","2B.7","2B.10"]}

SOURCE_CLAIM_JSON: {"title":"Declaración conjunta para el Diálogo de Alto Nivel de Seguridad entre México y Estados Unidos","publisher":"Embajada de México / Secretaría de Relaciones Exteriores","publication_date":"2021 (date not visible in opened excerpt)","url":"https://embamex.sre.gob.mx/vaticano/index.php/visitas-oficiales/18-comunicados-de-la-sre/704-declaracion-conjunta-para-el-dialogo-de-alto-nivel-de-seguridad-entre-mexico-y-estados-unidos","claim":"The Bicentennial Framework proposed cooperative security based on sovereignty, human rights, public health, prevention, reduced arms trafficking, and disruption of criminal networks rather than unilateral military action.","locator":"Lines 16-31","provisional_id":"E-AMLO22-2B-03","canonical_fact_key":"https://embamex.sre.gob.mx/vaticano/index.php/visitas-oficiales/18-comunicados-de-la-sre/704-declaracion-conjunta-para-el-dialogo-de-alto-nivel-de-seguridad-entre-mexico-y-estados-unidos|16-31|Bicentennial Framework cooperative security approach","disposition":"context","chapter_ids":["2B"],"methodology_ids":["2B.1","2B.3","2B.5","2B.7","2B.10"],"source_type":"bilateral government communiqué","source_confidence":"medium_high","source_confidence_reason":"Official bilateral framework setting out concrete intended cooperation, though implementation is not evaluated in the document.","final_evidence_use":"context","period_fit":"Framework preceded 2022 but governed the 2022 security relationship.","ruler_attribution":"Federal executive foreign and security policy under AMLO, implemented jointly with U.S. and Mexican agencies.","contrary_evidence":["The framework's aspirational language does not establish that violence, arms trafficking, or impunity declined."],"lenses":["2B.1","2B.3","2B.5","2B.7","2B.10"]}

SOURCE_CLAIM_JSON: {"title":"U.S.-Mexico Security Cooperation: From the Mérida Initiative to the Bicentennial Framework","publisher":"Congressional Research Service","publication_date":"2022-12-12","url":"https://www.congress.gov/crs_external_products/IF/PDF/IF10578/IF10578.26.pdf","claim":"CRS reported that organized-crime violence remained elevated in 2022 and that Mexico's security cooperation with the United States had struggled to fulfill its commitments.","locator":"PDF p. 1, lines 4-32","provisional_id":"E-AMLO22-2B-04","canonical_fact_key":"https://www.congress.gov/crs_external_products/IF/PDF/IF10578/IF10578.26.pdf|p.1|elevated violence and incomplete security commitments","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.2","2B.3","2B.5","2B.9","2B.10"],"source_type":"nonpartisan legislative research report","source_confidence":"high","source_confidence_reason":"CRS synthesis for Congress with explicit caveats and target-year context.","final_evidence_use":"final_evidence","period_fit":"Updated 12 December 2022 and explicitly discusses 2022.","ruler_attribution":"Attributes policy direction and security strategy to the López Obrador administration, while recognizing bilateral and institutional constraints.","contrary_evidence":["The report discusses national violence and cooperation outcomes without assigning every criminal act to the President."],"lenses":["2B.2","2B.3","2B.5","2B.9","2B.10"]}

SOURCE_CLAIM_JSON: {"title":"U.S.-Mexico Security Cooperation: From the Mérida Initiative to the Bicentennial Framework","publisher":"Congressional Research Service","publication_date":"2022-12-12","url":"https://www.congress.gov/crs_external_products/IF/PDF/IF10578/IF10578.26.pdf","claim":"CRS reported that AMLO criticized the Mérida Initiative and reduced federal security cooperation, but later supported military involvement in public security through 2028 and moved the National Guard toward the Defense Ministry.","locator":"PDF pp. 1-2, lines 78-119","provisional_id":"E-AMLO22-2B-05","canonical_fact_key":"https://www.congress.gov/crs_external_products/IF/PDF/IF10578/IF10578.26.pdf|pp.1-2|AMLO security-policy shift and National Guard militarization","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.2","2B.3","2B.4","2B.5","2B.8","2B.9"],"source_type":"nonpartisan legislative research report","source_confidence":"high","source_confidence_reason":"Contemporaneous CRS account of policy changes, institutional design, and competing expert concerns.","final_evidence_use":"final_evidence","period_fit":"Updated during the target year and covers the September 2022 reform.","ruler_attribution":"Strong attribution to AMLO's administration for the policy direction; legislative approval and military implementation were shared institutional acts.","contrary_evidence":["The government justified continued military participation by citing persistent violence and security needs; CRS also records cooperation and enforcement activity."],"lenses":["2B.2","2B.3","2B.4","2B.5","2B.8","2B.9"]}

SOURCE_CLAIM_JSON: {"title":"U.S.-Mexico Security Cooperation: From the Mérida Initiative to the Bicentennial Framework","publisher":"Congressional Research Service","publication_date":"2022-12-12","url":"https://www.congress.gov/crs_external_products/IF/PDF/IF10578/IF10578.26.pdf","claim":"CRS described the Bicentennial Framework as having three pillars—protect people, prevent transborder crime, and pursue criminal networks—and reported both praise for its focus on arms trafficking and criticism that it repackaged older programs or deemphasized institutional reform.","locator":"PDF p. 2, lines 135-166","provisional_id":"E-AMLO22-2B-06","canonical_fact_key":"https://www.congress.gov/crs_external_products/IF/PDF/IF10578/IF10578.26.pdf|p.2|mixed assessment of Bicentennial Framework","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.1","2B.3","2B.5","2B.7","2B.10"],"source_type":"nonpartisan legislative research report","source_confidence":"high","source_confidence_reason":"CRS records both official goals and contrary expert assessments.","final_evidence_use":"final_evidence","period_fit":"Updated 12 December 2022; framework implementation was active during 2022.","ruler_attribution":"Federal policy choice shared with U.S. counterparts and Mexican agencies.","contrary_evidence":["The same source reports new initiatives and observers who viewed the framework as revitalizing bilateral cooperation."],"lenses":["2B.1","2B.3","2B.5","2B.7","2B.10"]}

SOURCE_CLAIM_JSON: {"title":"Annual Report of the Inter-American Commission on Human Rights 2022: Mexico","publisher":"Inter-American Commission on Human Rights","publication_date":"2023-03-07","url":"https://www.oas.org/en/iachr/docs/annual/2022/Chapters/14-IA2022_Cap_5_MX_EN.pdf","claim":"The IACHR reported that Mexico's September 2022 reforms transferred National Guard control to Sedena, extended armed-forces participation in public security to 2028, and raised concerns about civilian oversight and militarization.","locator":"PDF pp. 1005-1008, paragraphs 9-17; lines 130-185 and 227-238","provisional_id":"E-AMLO22-2B-07","canonical_fact_key":"https://www.oas.org/en/iachr/docs/annual/2022/Chapters/14-IA2022_Cap_5_MX_EN.pdf|pp.1005-1008|National Guard transfer and military public-security role","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.2","2B.3","2B.4","2B.5","2B.8","2B.9"],"source_type":"regional human-rights monitoring report","source_confidence":"high","source_confidence_reason":"Independent IACHR follow-up using state submissions, civil-society material, hearings, and other public sources.","final_evidence_use":"final_evidence","period_fit":"Report evaluates information requested for 2022 and records September-October 2022 reforms.","ruler_attribution":"Strong policy attribution to the federal executive and governing coalition, with Congress and courts as material constraints.","contrary_evidence":["The Mexican State reported that the National Guard's purpose was to protect life, liberty, integrity, property, and public order with full respect for human rights."],"lenses":["2B.2","2B.3","2B.4","2B.5","2B.8","2B.9"]}

SOURCE_CLAIM_JSON: {"title":"Annual Report of the Inter-American Commission on Human Rights 2022: Mexico","publisher":"Inter-American Commission on Human Rights","publication_date":"2023-03-07","url":"https://www.oas.org/en/iachr/docs/annual/2022/Chapters/14-IA2022_Cap_5_MX_EN.pdf","claim":"The IACHR reported that National Guard use-of-force reporting was opaque and that CNDH complaints from January-April 2022 included allegations of arbitrary use of force.","locator":"PDF pp. 1009-1010, paragraphs 25-28; lines 320-337","provisional_id":"E-AMLO22-2B-08","canonical_fact_key":"https://www.oas.org/en/iachr/docs/annual/2022/Chapters/14-IA2022_Cap_5_MX_EN.pdf|pp.1009-1010|National Guard force reporting opacity and complaints","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.4","2B.5","2B.9"],"source_type":"regional human-rights monitoring report","source_confidence":"high","source_confidence_reason":"IACHR assessment with cited statutory requirements and CNDH complaint material.","final_evidence_use":"final_evidence","period_fit":"Covers January-April 2022 complaints and 2022 reporting obligations.","ruler_attribution":"Institutional federal-security attribution; complaints do not prove AMLO's personal involvement or that every allegation was substantiated.","contrary_evidence":["IACHR also found formal compliance with the existence of a national use-of-force law while continuing to monitor implementation."],"lenses":["2B.4","2B.5","2B.9"]}

SOURCE_CLAIM_JSON: {"title":"Annual Report of the Inter-American Commission on Human Rights 2022: Mexico","publisher":"Inter-American Commission on Human Rights","publication_date":"2023-03-07","url":"https://www.oas.org/en/iachr/docs/annual/2022/Chapters/14-IA2022_Cap_5_MX_EN.pdf","claim":"The Mexican State reported extensive National Guard human-rights and use-of-force training through 2022, but the IACHR kept the recommendation pending because training's effect on civilian policing was not demonstrated.","locator":"PDF pp. 1008-1009, paragraphs 18-21; lines 239-284","provisional_id":"E-AMLO22-2B-09","canonical_fact_key":"https://www.oas.org/en/iachr/docs/annual/2022/Chapters/14-IA2022_Cap_5_MX_EN.pdf|pp.1008-1009|National Guard training and pending compliance","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.4","2B.5","2B.7","2B.9"],"source_type":"regional human-rights monitoring report","source_confidence":"high","source_confidence_reason":"The report preserves both the State's training evidence and the IACHR's independent qualification.","final_evidence_use":"final_evidence","period_fit":"Training figures include programs through December 2022.","ruler_attribution":"Federal institutional policy and training responsibility; outcomes remain shared and not personally attributable without further evidence.","contrary_evidence":["The IACHR commended progress in training, while finding that the recommendation remained pending."],"lenses":["2B.4","2B.5","2B.7","2B.9"]}

SOURCE_CLAIM_JSON: {"title":"Mexico: Militarization of public security will lead to more human rights violations and perpetuate impunity","publisher":"Amnesty International","publication_date":"2022-09 (month shown in source URL)","url":"https://www.amnesty.org/en/latest/news/2022/09/mexico-militarizing-public-security-human-rights-violations-impunity/","claim":"Amnesty warned that reforms placing the National Guard under Defense Ministry control and permitting military personnel to serve in it would increase human-rights and impunity risks; it cited the UN Committee on Enforced Disappearances' call to abandon the militarized approach.","locator":"Lines 76-82","provisional_id":"E-AMLO22-2B-10","canonical_fact_key":"https://www.amnesty.org/en/latest/news/2022/09/mexico-militarizing-public-security-human-rights-violations-impunity/|76-82|Amnesty and UN concern over militarized security","disposition":"final_evidence","chapter_ids":["2B"],"methodology_ids":["2B.2","2B.3","2B.4","2B.5","2B.9","2B.10"],"source_type":"international human-rights analysis","source_confidence":"high","source_confidence_reason":"Contemporaneous Amnesty assessment incorporating a cited UN treaty-body recommendation.","final_evidence_use":"final_evidence","period_fit":"Directly concerns September 2022 reforms and an April 2022 UN recommendation.","ruler_attribution":"Strong policy attribution to the AMLO administration, while alleged abuses remain distributed across military and civilian institutions.","contrary_evidence":["The government presented militarization as necessary to address persistent violence and framed the National Guard as disciplined and professional."],"lenses":["2B.2","2B.3","2B.4","2B.5","2B.9","2B.10"]}

SOURCE_CLAIM_JSON: {"title":"GAO-23-103795: U.S. Assistance to Mexico","publisher":"U.S. Government Accountability Office","publication_date":"2023-09-12","url":"https://www.gao.gov/assets/d23103795.pdf","claim":"GAO reported that the United States and Mexico had reduced or changed security cooperation under the Bicentennial Framework and that State lacked adequate milestones and monitoring to assess overall progress.","locator":"PDF pp. 6-10 and p. 34, lines 326-354 and 1288-1302","provisional_id":"E-AMLO22-2B-11","canonical_fact_key":"https://www.gao.gov/assets/d23103795.pdf|pp.6-10,34|Bicentennial Framework monitoring and effectiveness gaps","disposition":"context","chapter_ids":["2B"],"methodology_ids":["2B.1","2B.5","2B.7","2B.9","2B.10"],"source_type":"government audit report","source_confidence":"high","source_confidence_reason":"Independent GAO audit with formal recommendations concerning monitoring and evaluation.","final_evidence_use":"context","period_fit":"Published after 2022 but evaluates the framework and U.S.-Mexico assistance through FY2022.","ruler_attribution":"Shared bilateral responsibility; does not independently establish AMLO's personal conduct.","contrary_evidence":["GAO records continuing framework goals and cooperation; its finding concerns measurement and accountability, not proof that all cooperation failed."],"lenses":["2B.1","2B.5","2B.7","2B.9","2B.10"]}

